window.COT_TPL=window.COT_TPL||{};
window.COT_TPL["BBP"]={css:"@font-face{font-family:'Source Code Pro';font-style:normal;font-weight:300;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Source Code Pro';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Source Code Pro';font-style:normal;font-weight:500;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}@font-face{font-family:'Source Code Pro';font-style:normal;font-weight:600;font-display:block;src:url(data:font/woff2;base64,) format('woff2')}\n\n*{box-sizing:border-box;margin:0;padding:0}\nhtml{background:#d9d9d6}\nbody{background:#d9d9d6;-webkit-print-color-adjust:exact;print-color-adjust:exact;padding:72px 0 40px}\n.page{width:210mm;height:297mm;margin:0 auto 14px;position:relative;overflow:hidden;background:#fff;box-shadow:0 2px 14px rgba(0,0,0,.18);outline:none}\nimg{display:block}\n.tb{position:fixed;top:0;left:0;right:0;z-index:50;background:#1d1d1b;color:#eee;font:13px/1.3 -apple-system,\"Helvetica Neue\",Arial,sans-serif}\n.tb-in{max-width:1100px;margin:0 auto;padding:10px 16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.tb-name{font-weight:600;margin-right:6px}\n.tb button{font:inherit;border:1px solid #666;background:#2c2c2a;color:#fff;padding:6px 12px;border-radius:6px;cursor:pointer}\n.tb button:hover{background:#3a3a37}\n.tb button.on{border-color:#9bc59d;color:#cfe8d0}\n.tb-hint{color:#aaa;font-size:11.5px;flex:1 1 300px}\n#rowTools{position:absolute;display:none;gap:3px;z-index:60}\n#rowTools button{width:26px;height:26px;border-radius:13px;border:1px solid #999;background:#fff;cursor:pointer;font-size:13px;line-height:1}\n#rowTools button:hover{background:#eee}\nbody.editing img.swap{cursor:pointer}\nbody.editing img.swap:hover{outline:2px dashed rgba(200,160,80,.9);outline-offset:-2px}\nbody.editing .page [contenteditable],body.editing .page{caret-color:#c00}\n@page{size:A4;margin:0}\n@media print{\n  html,body{background:#fff;padding:0}\n  .no-print{display:none!important}\n  .page{margin:0;box-shadow:none;break-after:page;page-break-after:always}\n  .page:last-of-type{break-after:auto;page-break-after:auto}\n}\n\n\n/* ====== BATÁN BUSINESS PARK · Manual de marca V1 ======\n   Primarios: Verde (C83 M32 Y79 K53) · Dorado #B6885C\n   Secundarios: verde #3B6538 · verde grisáceo #5C796B · beige #E3C7B2 · negro\n   Tipografías del manual (se usan si están instaladas en el equipo; Source Code va embebida):\n   Títulos: Blacker Display Regular · Encabezados: Centrale Sans Bold\n   Subtítulos / etiquetas: Bahnschrift Regular · Cuerpo de texto: Source Code (Adobe) */\n:root{\n  --verde:#1B402D; --verde-deep:#0F2318; --verde2:#3B6538; --verde-gris:#5C796B;\n  --oro:#B6885C; --oro-l:#C9A96E; --oro-p:#E8D5B0; --beige:#E3C7B2; --beige-l:#F6EEE6; --beige-xl:#FBF7F2;\n  --tx:#1E2420; --tx2:#4A524D; --tx3:#8A8F8B; --line:#E4DACE;\n  --serif:\"Blacker Display\",\"Blacker Pro Display\",\"BlackerDisplay-Regular\",Georgia,serif; --head:\"Centrale Sans\",\"Centrale Sans Bold\",\"CentraleSans-Bold\",\"Bahnschrift\",Helvetica,Arial,sans-serif; --sans:\"Bahnschrift\",\"Helvetica Neue\",Helvetica,Arial,sans-serif; --mono:\"Source Code Pro\",Menlo,monospace;\n}\n.page{font-family:var(--mono);font-weight:300;color:var(--tx);font-size:8.6pt;line-height:1.5;font-variant-numeric:lining-nums tabular-nums}\nb,strong{font-weight:500;color:var(--verde)}\n.cap{font-family:var(--sans);font-weight:400;text-transform:uppercase;letter-spacing:.22em}\n.num{font-family:var(--mono);font-variant-numeric:tabular-nums}\n/* hero */\n.hero{position:relative;height:236px;color:#fff;overflow:hidden}\n.hero img.bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n.hero .shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(15,35,24,.88) 0%,rgba(15,35,24,.55) 42%,rgba(15,35,24,.08) 78%),linear-gradient(0deg,rgba(15,35,24,.45),rgba(15,35,24,0) 55%);pointer-events:none}\n.hero .in{position:absolute;inset:0;padding:30px 52px 0}\n.hero .logo{height:50px;width:auto}\n.hero .ref{position:absolute;top:36px;line-height:1.7;right:52px;text-align:right;font-size:6.6pt;color:var(--oro-p)}\n.hero .kick{margin-top:28px;font-size:6.8pt;color:var(--oro-l)}\n.hero h1{font-family:var(--serif);font-weight:400;font-size:27pt;line-height:1.08;margin-top:8px}\n.hero h1 em{font-style:normal;color:var(--oro-p)}\n.hero .for{font-family:var(--sans);font-size:9.6pt;margin-top:9px;color:#E9E4DA}\n.hero .for b{color:#fff;font-weight:400}\n.band{background:var(--oro);color:#fff;font-size:7.4pt;padding:9px 52px;letter-spacing:.3em}\n.kpis{display:grid;grid-template-columns:1fr 1fr 1.15fr;border-bottom:1px solid var(--line)}\n.kpis>div{padding:15px 22px 14px 52px;background:var(--beige-l);border-right:1px solid var(--line);min-height:82px}\n.kpis>div+div{padding-left:52px}\n.kpis>div:last-child{background:var(--verde);border:0}\n.kpis .l{font-size:6.3pt;color:var(--tx3);line-height:1.45}\n.kpis .v{font-family:var(--serif);font-size:17pt;margin-top:3px;color:var(--verde)}\n.kpis .v small{font-size:8pt}\n.kpis>div:last-child .l{color:var(--oro-l)}\n.kpis>div:last-child .v{color:#fff}\n.body{padding:20px 52px 0}\n.intro{font-size:9.2pt;color:var(--tx2);line-height:1.6}\nh2{font-family:var(--head);font-size:8pt;font-weight:700;letter-spacing:.24em;text-transform:uppercase;color:var(--verde);padding-bottom:8px;border-bottom:1px solid var(--oro);margin:20px 0 10px}\ntable{width:100%;border-collapse:collapse}\n.ficha td{padding:6px 8px;border-bottom:1px solid var(--line);vertical-align:middle;font-size:8.6pt}\n.ficha td.k{font-family:var(--sans);font-size:6.8pt;font-weight:400;letter-spacing:.2em;text-transform:uppercase;color:var(--tx3);width:20%}\n.ficha td.v{width:30%}\n.ficha td.v.num{font-size:8.4pt}\n.plano{margin-top:6px;text-align:center}\n.plano img{width:100%;max-width:640px;margin:0 auto}\n.cap-img{font-family:var(--sans);font-size:6.6pt;color:var(--tx3);letter-spacing:.2em;text-transform:uppercase;text-align:center;margin-top:7px}\n.foot{position:absolute;left:0;right:0;bottom:0;height:46px;background:var(--verde);color:var(--oro-p);display:flex;justify-content:space-between;align-items:center;gap:18px;padding:0 52px;font-family:var(--sans);font-size:6.6pt;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap}\n.foot .r{color:var(--oro-l)}\n.foot .lg{display:flex;align-items:center;gap:12px}\n.foot .lg img{height:15px;width:auto}\n.foot .lg img.bt{height:18px}\n.foot .lg i{width:1px;height:20px;background:rgba(232,213,176,.45)}\n.foot .tx{flex:1;text-align:center}\n/* páginas interiores */\n.top{display:flex;justify-content:space-between;align-items:center;padding:24px 52px 14px;border-bottom:1px solid var(--line)}\n.top .logo{height:40px}\n.top .r{text-align:right}\n.top .r .a{font-family:var(--head);font-size:7.4pt;font-weight:700;letter-spacing:.3em;color:var(--verde)}\n.top .r .b{font-family:var(--sans);font-size:6.8pt;letter-spacing:.25em;color:var(--tx3);margin-top:4px;text-transform:uppercase}\n.det{width:100%}\n.det-wrap{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;align-items:start}\n.det th{background:var(--verde);color:#fff;font-family:var(--sans);font-size:6.6pt;font-weight:400;letter-spacing:.2em;text-transform:uppercase;padding:7px 8px;text-align:right}\n.det th:first-child{text-align:left}\n.det td{font-family:var(--mono);font-weight:400;font-size:7.6pt;padding:2.6px 8px;border-bottom:1px solid var(--line);text-align:right;color:var(--tx)}\n.det td:first-child{text-align:left;font-weight:500;color:var(--verde)}\n.tot{display:flex;justify-content:space-between;background:var(--beige-l);padding:9px 10px;margin-top:10px;font-size:7.8pt;color:var(--tx2)}\n.tot b{font-weight:700}\nul.dots{list-style:none;columns:2;column-gap:26px}\nul.dots li{break-inside:avoid;position:relative;padding-left:12px;margin-bottom:6px;font-size:8.3pt;color:var(--tx2);line-height:1.5}\nul.dots li:before{content:\"\";position:absolute;left:0;top:.6em;width:5px;height:5px;background:var(--oro);transform:rotate(45deg)}\n.photo{position:relative;height:150px;overflow:hidden}\n.photo img{width:100%;height:100%;object-fit:cover}\n.photo .tag{position:absolute;right:52px;bottom:12px;background:rgba(15,35,24,.82);color:var(--oro-p);font-family:var(--sans);font-size:6.4pt;letter-spacing:.22em;text-transform:uppercase;padding:5px 9px}\n.plan th{background:var(--verde);color:#fff;font-family:var(--sans);font-size:6.8pt;font-weight:400;letter-spacing:.22em;text-transform:uppercase;padding:7px 10px;text-align:left}\n.plan th.r,.plan td.r{text-align:right}\n.plan td{padding:7px 10px;border-bottom:1px solid var(--line);font-size:8.7pt}\n.plan td.r{font-family:var(--mono);font-size:8.2pt}\n.plan tbody tr:nth-child(odd) td{background:var(--beige-xl)}\n.plan tr.total td{background:var(--beige-l)!important;font-weight:600;color:var(--verde);border-bottom:2px solid var(--oro)}\n.note{font-size:8.2pt;color:var(--tx2);margin-top:9px}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:28px}\n.kv{table-layout:fixed}\n.kv td{height:34px;padding:0 6px;border-bottom:1px solid var(--line);font-size:7.8pt;vertical-align:middle;white-space:nowrap}\n.kv td.k{font-family:var(--sans);font-size:6.4pt;font-weight:400;letter-spacing:.12em;text-transform:uppercase;color:var(--tx3);white-space:normal;line-height:1.35}\n.kv td.r{text-align:right}\n.kv td.m{color:var(--tx3)}\n.kv tr.t td{font-weight:600;color:var(--verde)}\n.small{font-size:7.1pt;color:var(--tx3);line-height:1.5;margin-top:7px}\n\n/* ====== Datos del cliente (v2) ====== */\n.cli{display:grid;grid-template-columns:27mm 1.5fr .95fr .8fr .9fr 1.55fr;align-items:center;padding:0 52px;height:48px;background:var(--beige-xl);border-bottom:1px solid var(--line)}\n.cli .h{font-family:var(--head);font-weight:700;font-size:6.4pt;line-height:1.35;letter-spacing:.2em;text-transform:uppercase;color:var(--verde)}\n.cli .c{padding-left:11px;border-left:1px solid var(--line);min-width:0}\n.cli .l{font-family:var(--sans);font-size:5.9pt;letter-spacing:.16em;text-transform:uppercase;color:var(--tx3);line-height:1.3}\n.cli .v{font-family:var(--mono);font-weight:400;font-size:8.2pt;color:var(--tx);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.cli .v.n{color:var(--verde);font-weight:700}\n\nhtml,body{margin:0!important;padding:0!important;background:#fff!important}\n.page{margin:0!important;box-shadow:none!important;zoom:1!important}\n.no-print,.toolbar{display:none!important}\n.pp{margin-top:2px}.ppn{font-size:8.2pt;color:var(--tx2);margin-top:8px}.ppn b{color:var(--verde)}\n.page{break-inside:avoid}",
I:{"hero": "data:image/jpeg;base64,", "logo": "data:image/png;base64,", "ritofa": "data:image/png;base64,", "batan": "data:image/png;base64,", "logo2": "data:image/png;base64,", "oficina": "data:image/jpeg;base64,"},
build:function(c,I){ const $=c.$, e=c.e, n2=c.n2;
  const u0=c.u[0], piso=(String(u0.chip||'').match(/(\d+)/)||[])[1]||'', torre=(String(u0.meta||'').split('·')[1]||'').trim();
  const pisoTxt={'1':'Primer piso','2':'Segundo piso','3':'Tercer piso','4':'Cuarto piso'}[piso]||('Piso '+piso);
  const multi=c.n>1, nums=c.u.map(u=>u.num);
  const area=c.t.m2+c.t.m2_balcon+c.t.m2_terraza;
  const PG=c.pg, P=c.t.precio, cuotas=Math.max(1,c.plazo||1);
  const pago=`<table class="plan pp"><thead><tr><th>Etapa</th><th class="r">%</th><th class="r">Valor</th></tr></thead><tbody>
    <tr><td>Reserva</td><td class="r">${Math.round(PG.reserva*100)} %</td><td class="r">${$(P*PG.reserva)}</td></tr>
    <tr><td>Cuota a la firma de la promesa</td><td class="r">${Math.round(PG.firma*100)} %</td><td class="r">${$(P*PG.firma)}</td></tr>
    <tr><td>Entrada a financiar — ${cuotas} cuota${cuotas>1?'s':''} mensual${cuotas>1?'es':''}</td><td class="r">${Math.round(PG.saldo_entrada*100)} %</td><td class="r">${$(P*PG.saldo_entrada)}</td></tr>
    <tr><td>Saldo contra escritura — crédito hipotecario o contado</td><td class="r">${Math.round(PG.saldo_final*100)} %</td><td class="r">${$(P*PG.saldo_final)}</td></tr>
    <tr class="total"><td>Valor total</td><td class="r">100 %</td><td class="r">${$(P)}</td></tr>
  </tbody></table>
  <p class="ppn">La entrada a financiar se cancela en <b>${cuotas} cuota${cuotas>1?'s':''} mensual${cuotas>1?'es':''} de ${$(P*PG.saldo_entrada/cuotas)}</b>, a partir del mes siguiente a la firma de la promesa de compraventa.</p>`;

  const filas=c.u.map(u=>`<tr><td>${e(u.num)}</td><td class="r">${n2(u.m2)}</td><td class="r">${u.m2_balcon?n2(u.m2_balcon):(u.m2_terraza?n2(u.m2_terraza)+' (terraza)':'—')}</td><td class="r">${$(u.precio)}</td></tr>`).join('');
  return `
<section class="page">
  <div class="hero">
    <img class="bg" src="${I.hero}" alt="Batán Business Park">
    <div class="shade"></div>
    <div class="in">
      <img class="logo" src="${I.logo}" alt="Batán Business Park">
      <div class="ref cap">REF · ${e(c.numero)}<br>${e(c.mes)}</div>
      <div class="kick cap">COTIZACIÓN · ${e(c.numero)}</div>
      <h1>${multi?c.n+' oficinas':'Oficina '+e(nums[0])}<br><em>${e(pisoTxt)} · ${e(torre)}</em></h1>
      <div class="for">Preparada para <b>${e(c.cli.nombre)}</b></div>
    </div>
  </div>
  <div class="band cap">Nivel ${e(piso)} &nbsp;·&nbsp; ${e(torre)} &nbsp;·&nbsp; ${multi?'Oficinas '+e(nums.join(', ')):'Oficina '+e(nums[0])}</div>
  <div class="kpis">
    <div><div class="l cap">Área total</div><div class="v">${n2(area)} <small>m²</small></div></div>
    <div><div class="l cap">Precio por m²<br>${multi?'promedio':'de oficina'}</div><div class="v">${$(c.t.precio/c.t.m2)}</div></div>
    <div><div class="l cap">Valor total</div><div class="v">${$(c.t.precio)}</div></div>
  </div>
  <div class="cli">
    <div class="h">Datos del<br>cliente</div>
    <div class="c"><div class="l">Cliente</div><div class="v n">${e(c.cli.nombre)}</div></div>
    <div class="c"><div class="l">Cédula / RUC</div><div class="v">${e(c.cli.cedula)}</div></div>
    <div class="c"><div class="l">Fecha</div><div class="v">${e(c.fecha)}</div></div>
    <div class="c"><div class="l">Celular</div><div class="v">${e(c.cli.celular)}</div></div>
    <div class="c"><div class="l">Correo</div><div class="v">${e(c.cli.correo)}</div></div>
  </div>
  <div class="body">
    <p class="intro">Estimado/a ${e(c.cli.nombre)}:<br>Presentamos la cotización de ${multi?c.n+' oficinas contiguas':'la oficina '+e(nums[0])} en el ${e(pisoTxt.toLowerCase())} de Batán Business Park, ${e(torre)}, con valores de la lista de precios vigente.</p>
    <h2>Ficha de la ${multi?'propuesta':'oficina'}</h2>
    <table class="ficha"><tbody>
      <tr><td class="k">Proyecto</td><td class="v">Batán Business Park</td><td class="k">Promotora</td><td class="v">TECHCORP S.A.S.</td></tr>
      <tr><td class="k">Ubicación</td><td class="v">km 8.5 Vía a Samborondón</td><td class="k">Nivel</td><td class="v">${e(pisoTxt)}</td></tr>
      <tr><td class="k">${multi?'Oficinas':'Oficina'}</td><td class="v">${e(nums.join(', '))}</td><td class="k">Área de oficina${multi?'s':''}</td><td class="v">${n2(c.t.m2)} m²</td></tr>
      <tr><td class="k">${c.t.m2_terraza?'Terraza':'Balcón'}</td><td class="v">${c.t.m2_balcon||c.t.m2_terraza?n2(c.t.m2_balcon||c.t.m2_terraza)+' m²':'No aplica'}</td><td class="k">Tipo</td><td class="v">${e(u0.tipo||'Oficina')}</td></tr>
      <tr><td class="k"></td><td class="v"></td><td class="k">Valor total</td><td class="v"><b>${$(c.t.precio)}</b></td></tr>
    </tbody></table>
    <h2>Ubicación en el ${e(pisoTxt.toLowerCase())}</h2>
    <div class="plano"><img src="${c.plan}" alt="Planta" style="height:62mm;width:auto;max-width:100%"></div>
    <div class="cap-img">${e(pisoTxt)} · ${e(c.planCap||'')} resaltada${multi?'s':''}</div>
  </div>
  <div class="foot"><div class="lg"><img src="${I.ritofa}" alt="RITOFA"><i></i><img class="bt" src="${I.batan}" alt="Batán Proyectos Inmobiliarios"></div><span class="tx">Batán Business Park · km 8.5 Vía a Samborondón</span><span class="r">${e(c.numero)} · 1 / 2</span></div>
</section>
<section class="page">
  <div class="top">
    <img class="logo" src="${I.logo2}" alt="Batán Business Park">
    <div class="r"><div class="a">COTIZACIÓN ${e(c.numero)}</div><div class="b">${e(c.cli.nombre)}</div></div>
  </div>
  ${c.n>2?'':`<div class="photo"><img src="${I.oficina}" alt="Oficina tipo"><div class="tag">Imagen referencial · oficina tipo</div></div>`}
  <div class="body" style="padding-top:2px">
    ${multi?`<h2>Oficinas de la cotización</h2><table class="plan"><thead><tr><th>Oficina</th><th class="r">m² oficina</th><th class="r">Balcón / terraza m²</th><th class="r">Valor</th></tr></thead><tbody>${filas}</tbody></table>`:''}
    <h2>Plan de pagos</h2>
    ${pago}
    <h2>Condiciones generales</h2>
    <ul class="dots">
      <li>Valores en dólares de los Estados Unidos a precio de lista vigente, sujetos a cambio sin previo aviso.</li>
      <li>No incluyen IVA ni gastos notariales, de escrituración o de inscripción en el Registro de la Propiedad.</li>
      <li>La reserva se formaliza con la Solicitud de Reserva y la documentación de respaldo, sujetas a revisión y aprobación.</li>
      <li>Las áreas son referenciales y están sujetas a los planos aprobados y a la declaratoria de propiedad horizontal.</li>
      <li>Las imágenes y plantas son referenciales. Documento informativo; no constituye oferta vinculante.</li>
      <li>Asesor/a: ${e(c.asesor||'-')}.</li>
    </ul>
  </div>
  <div class="foot"><div class="lg"><img src="${I.ritofa}" alt="RITOFA"><i></i><img class="bt" src="${I.batan}" alt="Batán Proyectos Inmobiliarios"></div><span class="tx">Batán Business Park · km 8.5 Vía a Samborondón</span><span class="r">${e(c.numero)} · 2 / 2</span></div>
</section>`; }};
